import asyncio

async def act(page):
    # Scroll to the bottom of the homepage to ensure all content is loaded
    await page.evaluate('window.scrollTo(0, document.body.scrollHeight)')
    await asyncio.sleep(3)  # Wait for any lazy-loaded content, especially pagination

    # Use page.evaluate to get all link URLs on the page
    links = await page.evaluate('''
        () => {
            const anchors = Array.from(document.querySelectorAll('a'));
            return anchors.map(a => a.href);
        }
    ''')

    # Search for a URL that contains 'paged=6' or similar pattern for pagination
    target_url = None
    for url in links:
        if '6' in url and ('paged' in url or 'page' in url.lower()):
            target_url = url
            break

    if target_url:
        # Navigate to the target URL for page 6
        await page.goto(target_url)
        await page.wait_for_load_state('load')
        return f"Successfully navigated to page 6 of the blog feed via URL: {target_url}."
    else:
        return "No pagination link for page 6 found after scrolling and checking all links."

